/* Einstieg und Anleitung, ohne den gespeicherten Lernstand zu verändern. */
function hasLearningProgress(){return Boolean(state.started||state.done.length||state.station>0||state.phase>0||Object.keys(state.answers).length||Object.keys(state.tasks).length||Object.values(state.notes).some(value=>String(value??'').trim()));}
function focusContent(){$('#main').focus();window.scrollTo({top:0,behavior:'instant'});}
function showHome(){home=true;notebook=false;history.replaceState(null,'','#start');render(true);}
function resumeLearning(){home=false;notebook=false;state.started=true;history.replaceState(null,'',`#station-${state.station+1}`);render(true);}
function showNotebook(){home=false;notebook=true;history.replaceState(null,'','#vergleich');render(true);}
function renderHome(){const continuing=hasLearningProgress(),all=state.done.length===5;$('#main').innerHTML=`<div class="welcome-heading"><p class="welcome-kicker">Lernzirkel · Wirtschaft · Klasse 11</p><h1>Plan und Markt verstehen</h1><p class="welcome-intro">Wer entscheidet, was produziert wird, wie Preise entstehen und wer die Güter erhält? In fünf Stationen vergleichst du Zentralverwaltungswirtschaft und freie Marktwirtschaft. Am Ende hast du eine eigene Vergleichstabelle und kannst die Unterschiede begründen.</p><ul class="welcome-facts" aria-label="Rahmen der Bearbeitung"><li>5 Stationen</li><li>Etwa 90–120 Minuten</li><li>Selbstständig im eigenen Tempo</li></ul><div class="welcome-actions"><button class="primary" ${all?'data-home-results':'data-resume'}>${all?'Meine Ergebnisse ansehen':continuing?'Weiterlernen: Station '+(state.station+1):'Lernzirkel starten'} <span aria-hidden="true">→</span></button>${continuing?'<button class="secondary" data-station="0">Station 1 öffnen</button>':''}</div>${continuing?`<p class="welcome-resume small">Dein Lernstand ist vorhanden: ${state.done.length} von 5 Stationen abgeschlossen. Zuletzt geöffnet: Station ${state.station+1}, „${['Verstehen','Anwenden','Festhalten'][state.phase]}“. Deine bisherigen Antworten bleiben erhalten.</p>`:''}</div><section class="sheet welcome-method" aria-labelledby="method-title"><h2 id="method-title">So bearbeitest du jede Station</h2><ol class="method-steps"><li><span class="method-number" aria-hidden="true">1</span><div><h3>Verstehen</h3><p>Lies den Text aufmerksam und betrachte die Grafiken. Unbekannte Wörter kannst du über „Begriffe nachschlagen“ klären. Die Denkfragen helfen dir, die wichtigsten Zusammenhänge zu erkennen.</p></div></li><li><span class="method-number" aria-hidden="true">2</span><div><h3>Anwenden</h3><p>Bearbeite die Zuordnungen und Fragen. Tippe auf „Antwort prüfen“ oder die Prüftaste der Aufgabe. Nutze bei Fehlern zunächst den Hinweis und versuche es noch einmal. In Station 3 untersuchst du außerdem selbst, was bei verschiedenen Preisen passiert.</p></div></li><li><span class="method-number" aria-hidden="true">3</span><div><h3>Festhalten</h3><p>Formuliere deine Ergebnisse in eigenen Worten. Ein Lösungsvorschlag wird erst nach einer eigenen Eingabe verfügbar; bei einem Vergleichspaar müssen beide Felder Text enthalten. Vergleiche und verbessere deine Antwort, bestätige den Selbstcheck und wähle „Station abschließen“.</p></div></li></ol><p class="method-note"><strong>Wann ist eine Station fertig?</strong> Wenn die Aufgaben richtig geprüft, die nötigen Notizen ergänzt und der Selbstcheck bestätigt sind. Freie Texte werden von dir selbst kontrolliert, nicht automatisch bewertet.</p></section><section class="welcome-route" aria-labelledby="route-title"><h2 id="route-title">Dein Weg durch die fünf Stationen</h2><p>Arbeite möglichst der Reihe nach. Du kannst jederzeit zurückgehen und Antworten verbessern.</p><ol>${stations.map((s,i)=>`<li><button data-station="${i}"><span class="welcome-station-number" aria-hidden="true">${i+1}</span><span><strong>${s.short}</strong><span>${s.sub}</span></span><span aria-hidden="true">→</span></button></li>`).join('')}</ol></section><section class="sheet welcome-finish" aria-labelledby="finish-title"><h2 id="finish-title">Ergebnisse sichern und weiterarbeiten</h2><p>Deine Eingaben werden automatisch <strong>in diesem Browser auf diesem Gerät</strong> gespeichert. Verwende nach einer Pause möglichst dasselbe Gerät und denselben Browser. Ein Gerätewechsel oder das Löschen der Browserdaten übernimmt deinen Lernstand nicht.</p><p>Öffne am Ende <strong>„Meine Vergleichstabelle“</strong>. Lade deine Ergebnisse als Datei herunter oder sichere sie über „Drucken / als PDF sichern“. Gib die Datei so ab, wie deine Lehrkraft es vorgibt. Die Seite sendet deine Antworten nicht automatisch an sie.</p><p>Auf einem gemeinsam genutzten iPad: Sichere zuerst deine Ergebnisse und wähle danach „Lernfortschritt zurücksetzen“.</p><p class="small">Plane etwa 90–120 Minuten für die Bearbeitung ein. Für eine gemeinsame Auswertung kommt zusätzliche Zeit dazu. Die Partneraufgabe ist freiwillig; alle Pflichtaufgaben sind allein lösbar.</p><div class="welcome-actions"><button class="primary" ${all?'data-home-results':'data-resume'}>${all?'Meine Ergebnisse ansehen':continuing?'An letzter Stelle weiterlernen':'Mit Station 1 beginnen'}</button></div></section>`;}
document.addEventListener('click',e=>{const button=e.target.closest('button');if(!button)return;if(button.hasAttribute('data-resume'))resumeLearning();if(button.hasAttribute('data-home-results'))showNotebook();});
function readPageRoute(){const match=location.hash.match(/^#station-([1-5])$/);if(match){const next=Number(match[1])-1;if(state.station!==next)state.phase=0;state.station=next;state.started=true;home=false;notebook=false;}else if(location.hash==='#vergleich'){home=false;notebook=true;}else{home=true;notebook=false;}}
window.addEventListener('hashchange',()=>{if(location.hash==='#main')return;readPageRoute();render(true);});
